<template><div class="aw"><p v-if="state.sourcePhase==='submitting'" role="status">{{t('saving')}}</p><p v-if="state.navigationBlocked" role="alert">{{t('pendingLeave')}}</p><p v-if="state.capabilityPhase==='unknown'||state.capabilityPhase==='loading'" role="status">{{t('loading')}}</p><p v-if="state.capabilityPhase==='unavailable'" role="alert">{{t('capabilityUnknown')}}</p><p v-if="state.capabilityPhase==='enabled'&&!state.capabilities?.canAdopt" role="status">{{t('noActions')}}</p><p v-if="state.capabilityPhase==='denied'" role="alert">{{t('denied')}}</p><p v-if="state.capabilityPhase==='disabled'">{{t('featureOff')}}</p><p v-if="state.sourcePhase==='uncertain'" class="aw-notice" role="status">{{t('uncertain')}}</p><p v-if="state.sourcePhase==='conflict'" class="aw-notice" role="status">{{t('conflict')}}</p><p v-if="state.sourcePhase==='rejected'" role="alert">{{t('rejected')}}</p><p v-if="state.error" role="alert">{{t(state.error)}}</p><p v-if="state.sourcePhase==='succeeded'" role="status">{{t(state.sourceOperation==='adopt'?'CREATED':'saved')}}</p><div class="aw-controls"><button v-if="state.sourcePhase==='uncertain'" type="button" @click="retry">{{t('retryOriginal')}}</button><button v-if="['conflict','rejected'].includes(state.sourcePhase)" type="button" @click="newDecision">{{t('newDecision')}}</button><button v-if="['unknown','unavailable','denied'].includes(state.capabilityPhase)" type="button" @click="flow.loadCapabilities()">{{t('refresh')}}</button></div></div></template>
<script setup>
import {t} from '@/utils/alertWorkflowCopy'
const props=defineProps({flow:{type:Object,required:true},sourceType:{type:String,required:true}}),emit=defineEmits(['saved']),state=props.flow.state
async function retry(){const result=await props.flow.saveSource(props.sourceType,{}, {retry:true});if(result.status==='succeeded')emit('saved',result)}
async function newDecision(){const result=await props.flow.loadCapabilities();if(['enabled','disabled'].includes(result.status)){if(state.sourceOperation!=='save'&&state.source){const source=state.source,read=await props.flow.readSource(source.sourceType,source.id);if(read.status!=='succeeded')return}props.flow.newDecision('source');emit('refresh')}}
</script>
